                .andExpect(jsonPath("$.receipts[0].shardDigest").value(wrongDigest))
                .andExpect(jsonPath("$.events[0].result").value("INTEGRITY_FAILED"));

        // 新代次从零接收：正确分片集齐后可安装并回执成功
