        mockMvc.perform(get("/api/releases/" + releaseId + "/tasks"))
                .andExpect(jsonPath("$.tasks.length()").value(2))
                .andExpect(jsonPath("$.tasks[0].status").value("INTEGRITY_FAILED"))
                .andExpect(jsonPath("$.tasks[1].status").value("SUCCESS"));
    }

