        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM integrity_event", Long.class)).isZero();
    }

    @Test
    void 未集齐禁止安装回执_响应携带实际与要求数量() throws Exception {
        registerDevice("r-dev", "d1", "m1", 1);
